import json
import os
import re
import xml.etree.ElementTree as ET

# Register namespace prefix so ElementTree writes 'hp:' instead of 'ns0:'
NS_HP = 'http://www.hancom.co.kr/hwpml/2010/HWPML'
ET.register_namespace('hp', NS_HP)

HP = '{' + NS_HP + '}'

def load_json(path):
    with open(path, 'r', encoding='utf-8') as f:
        return json.load(f)

def get_parent_map(root):
    return {c: p for p in root.iter() for c in p}

def merge_split_placeholders(root, parent_map):
    modified_paras = set()
    for run in root.iter(HP + 'run'):
        t_elements = [child for child in run if child.tag == HP + 't']
        if len(t_elements) <= 1:
            continue
        combined = ''.join(t.text or '' for t in t_elements)
        if '{{' in combined:
            # Merge all hp:t into the first one
            first = t_elements[0]
            first.text = combined
            for t in t_elements[1:]:
                run.remove(t)
            # Mark parent paragraph as modified
            p = run
            while p is not None and p.tag != HP + 'p':
                p = parent_map.get(p)
            if p is not None:
                modified_paras.add(id(p))
    return modified_paras

def replace_placeholders(root, mapping, parent_map):
    modified_paras = set()
    for t_elem in root.iter(HP + 't'):
        old_text = t_elem.text or ''
        new_text = old_text
        for key, val in mapping.items():
            new_text = new_text.replace(key, val)
        if new_text != old_text:
            t_elem.text = new_text
            p = t_elem
            while p is not None and p.tag != HP + 'p':
                p = parent_map.get(p)
            if p is not None:
                modified_paras.add(id(p))
    return modified_paras

def parse_months(text):
    # Range format: YYYY-MM ~ YYYY-MM or YYYY.MM ~ YYYY.MM
    m = re.search(r'(\d{4})[-.](\d{2})\s*~\s*(\d{4})[-.](\d{2})', text)
    if m:
        sy, sm, ey, em = map(int, m.groups())
        return (ey - sy) * 12 + (em - sm) + 1
    # Single month format: YYYY-MM or YYYY.MM
    m = re.search(r'(\d{4})[-.](\d{2})', text)
    if m:
        return 1
    return None

def append_month_annotations(root, data, parent_map):
    modified_paras = set()
    phase_keys = ['단계1', '단계2', '단계3']
    for t_elem in root.iter(HP + 't'):
        text = t_elem.text or ''
        for key in phase_keys:
            phase_str = data.get(key, '')
            if phase_str and phase_str in text:
                # Avoid double-annotation
                if '개월)' in text:
                    continue
                months = parse_months(phase_str)
                if months is not None:
                    t_elem.text = text + f' ({months}개월)'
                    p = t_elem
                    while p is not None and p.tag != HP + 'p':
                        p = parent_map.get(p)
                    if p is not None:
                        modified_paras.add(id(p))
                break
    return modified_paras

def remove_layout_cache(root, modified_para_ids):
    for p in root.iter(HP + 'p'):
        if id(p) in modified_para_ids:
            # Remove any child whose tag (case-insensitive) ends with linesegarray
            for child in list(p):
                local = child.tag.split('}')[-1]
                if local.lower() == 'linesegarray':
                    p.remove(child)

def process_xml_file(xml_path, data, mapping):
    tree = ET.parse(xml_path)
    root = tree.getroot()
    parent_map = get_parent_map(root)

    modified = set()
    modified |= merge_split_placeholders(root, parent_map)
    modified |= replace_placeholders(root, mapping, parent_map)
    modified |= append_month_annotations(root, data, parent_map)
    remove_layout_cache(root, modified)

    # Verify no placeholders remain
    xml_str = ET.tostring(root, encoding='utf-8').decode('utf-8')
    if '{{' in xml_str:
        raise ValueError(f"Unreplaced placeholders remain in {xml_path}")

    tree.write(xml_path, encoding='utf-8', xml_declaration=True)

def main():
    json_path = '/root/project_proposal.json'
    data = load_json(json_path)

    # Build placeholder mapping. Strip commas from budget but keep currency symbol.
    mapping = {}
    for key, val in data.items():
        placeholder = '{{' + key + '}}'
        if key == '예산':
            # Remove commas only, keep everything else (e.g., ₩)
            val = val.replace(',', '')
        mapping[placeholder] = val

    base_dir = '/tmp/hwpx_work/template_extracted'
    for root_dir, dirs, files in os.walk(base_dir):
        for fname in files:
            if fname.endswith('.xml'):
                xml_path = os.path.join(root_dir, fname)
                with open(xml_path, 'r', encoding='utf-8') as f:
                    raw = f.read()
                # Only process files that originally contain placeholders or phase text
                if '{{' in raw or '단계' in raw:
                    process_xml_file(xml_path, data, mapping)

if __name__ == '__main__':
    main()
